import * as bech32 from './lib/bech32/index.mjs';
import { ArgumentParser, ParserExit } from './lib/cli/argparse.mjs';
import { pyRepr } from './lib/python/repr.mjs';
import { print, writeStderr, writeStdout } from './lib/python/stdio.mjs';

function buildParser() {
  const parser = new ArgumentParser();
  parser.addArgument(['--a'], { type: String, required: true }); // HRP
  parser.addArgument(['--b'], { type: String, required: true }); // Segwit address
  return parser;
}

function main(argv) {
  const parser = buildParser();
  const args = parser.parseArgs(argv);

  const decoded = bech32.decode(args.a, args.b); // Decode segwit address
  // Python's `is not None`, not a truthiness test: witness version 0 is falsy
  // in JavaScript but is a perfectly good result here.
  if (decoded[0] !== null && decoded[1] !== null) {
    const [witver, witprog] = decoded;
    const converted = bech32.convertbits(witprog, 5, 8); // Convert 5-bit to 8-bit
    print(pyRepr(witver));
    print(pyRepr(converted));
  }
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (!(error instanceof ParserExit)) {
    throw error;
  }
  writeStdout(error.stdout);
  writeStderr(error.stderr);
  // Setting exitCode rather than calling process.exit() lets Node flush both
  // streams before the process goes away.
  process.exitCode = error.status;
