// A faithful port of the slice of Python's `argparse.ArgumentParser` that this
// CLI exercises: two required value-taking long options plus the automatic
// `-h/--help`, and no positionals.
//
// The token-classification and consumption algorithm follows CPython's
// `_parse_known_args` closely, because its quirks are observable:
//   * a required-argument error is raised before unrecognised arguments are
//     reported, so a missing `--a` wins over trailing junk;
//   * `-5` and `-1.5` are values (they look like negative numbers) while `-x`
//     and `-5x` are option strings, so `--b -x` fails with "expected one
//     argument" rather than storing "-x";
//   * `--h`, `--he` and `--hel` all resolve to `--help` by unique-prefix match;
//   * `--` is a separator that is itself left over as an unrecognised argument,
//     since no positional action is declared to absorb it.

import { basename } from 'node:path';

import { HELP, STORE, Action, destFromOptionStrings, makeHelpAction } from './actions.mjs';
import { ArgumentError, ParserExit } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';
import { pyRepr } from '../python/repr.mjs';

const PREFIX_CHARS = '-';

/** argparse's own "this token is a negative number, not an option" test. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** argparse's default `prog`: `os.path.basename(sys.argv[0])`. */
export function defaultProg() {
  const script = process.argv[1];
  return script === undefined ? '' : basename(script);
}

export class ArgumentParser {
  constructor({ prog = defaultProg(), addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addAction(makeHelpAction());
    }
  }

  addAction(action) {
    this.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  addArgument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    return this.addAction(
      new Action({
        optionStrings,
        dest: options.dest ?? destFromOptionStrings(optionStrings),
        kind: STORE,
        nargs: null,
        required: options.required === true,
        metavar: options.metavar ?? null,
        help: options.help ?? '',
        type: options.type ?? null,
      }),
    );
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** Print usage plus a message on stderr and terminate with status 2. */
  error(message) {
    throw new ParserExit(2, {
      stderr: `${this.formatUsage()}${this.prog}: error: ${message}\n`,
    });
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    try {
      return this.parseKnownArgsUnchecked(argv);
    } catch (error) {
      if (error instanceof ArgumentError) {
        this.error(error.message);
      }
      throw error;
    }
  }

  parseKnownArgsUnchecked(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === STORE) {
        namespace[action.dest] = null;
      }
    }

    // Classify every token up front: 'O' for something that looks like an
    // option, 'A' for a value, '-' for the `--` separator. Option matching then
    // works against this pattern rather than against the raw strings, which is
    // what makes `--b -- value` fail instead of storing "--".
    const pattern = [];
    const optionTuples = new Map();
    let index = 0;
    while (index < argv.length) {
      if (argv[index] === '--') {
        pattern.push('-');
        index += 1;
        while (index < argv.length) {
          pattern.push('A');
          index += 1;
        }
        break;
      }
      const tuple = this.parseOptional(argv[index]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, tuple);
        pattern.push('O');
      }
      index += 1;
    }

    const extras = [];
    const seen = new Set();
    const context = { argv, pattern, optionTuples, extras, seen, namespace };

    const optionIndices = [...optionTuples.keys()].sort((left, right) => left - right);
    const maxOptionIndex = optionIndices.length === 0 ? -1 : optionIndices[optionIndices.length - 1];
    let start = 0;
    while (start <= maxOptionIndex) {
      const next = optionIndices.find((candidate) => candidate >= start);
      if (next === undefined) {
        break;
