// Control-flow signals used by the argparse port.

/**
 * A recoverable parse failure. `ArgumentParser.parseKnownArgs` catches these and
 * converts them into a `parser.error(...)`, exactly as CPython's
 * `parse_known_args` does.
 *
 * The rendered form is `argument --a: expected one argument`, where the argument
 * name is every option string for the action joined by `/`.
 */
export class ArgumentError extends Error {
  constructor(action, detail) {
    super(action === null ? detail : `argument ${action.optionStrings.join('/')}: ${detail}`);
    this.name = 'ArgumentError';
  }
}

/**
 * A request to terminate, carrying whatever the parser wanted to emit first.
 * `--help` exits 0 with the help text on stdout; a usage error exits 2 with the
 * usage line plus the message on stderr.
 */
export class ParserExit extends Error {
  constructor(status, { stdout = '', stderr = '' } = {}) {
    super(`parser exit ${status}`);
    this.name = 'ParserExit';
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}
