ab('bc' + DEL, SHORT);
ab('bc', DEL + DEL);

// ------------------------------------- 5. the four excluded chars, exhaustively
for (const ch of EXCLUDED) {
  for (let i = 0; i <= SHORT.length; i += 1) {
    ab('bc', SHORT.slice(0, i) + ch + SHORT.slice(i));       // insert
  }
  for (let i = 0; i < SHORT.length; i += 1) {
    ab('bc', SHORT.slice(0, i) + ch + SHORT.slice(i + 1));   // substitute
  }
}
for (let i = 0; i < SHORT.length; i += 1) {
  ab('bc', SHORT.slice(0, i) + SHORT.slice(i + 1));          // delete
}
// same on the 42-char p2wpkh, data positions only
for (const ch of ['1', 'b', 'i', 'o']) {
  for (let i = 3; i < P2WPKH.length; i += 3) {
    ab('bc', P2WPKH.slice(0, i) + ch + P2WPKH.slice(i + 1));
  }
  ab('bc', P2WPKH + ch);
  ab('bc', ch + P2WPKH);
}
// uppercase address with excluded chars
for (const ch of ['1', 'B', 'I', 'O']) {
  const U = P2WPKH.toUpperCase();
  ab('bc', U.slice(0, 5) + ch + U.slice(6));
  ab('bc', U + ch);
}
// strings made only of excluded characters
for (const s of [
  '1', '11', '111', '1111111', '11111111', 'b', 'bb', 'bi', 'bio', 'boi1',
  'b1', 'i1', 'o1', '1b', '1i', '1o', '1bio', 'bio1bio', '1111111111',
  'bcbcbcb', 'IOB', 'BIO1BIO', 'oooooooo', 'iiiiiii1',
]) { ab('bc', s); ab('', s); ab(s, s); }

// ---------------------------- 6. HRPs that legitimately contain b / i / o / 1
for (const hrp of ['b', 'i', 'o', '1', 'bi', 'bio', 'b1i1o', 'oi1', 'a1b',
  '11', '1b1', 'bc1', '~', '!', '{|}', 'B', 'ab1b']) {
  const addr = segwitEncode(hrp, 1, [8, 128]);
  if (addr === null) continue;
  ab(hrp, addr);
  ab(hrp, addr.toUpperCase());
  ab(hrp.toUpperCase(), addr);
  ab(hrp, addr + '1');
  ab(hrp, addr + 'b');
  ab(hrp, '1' + addr);
  ab(hrp, 'b' + addr);
  const sep = addr.lastIndexOf('1');
  for (const ch of ['1', 'b', 'i', 'o']) {
    ab(hrp, addr.slice(0, sep + 1) + ch + addr.slice(sep + 2));
    ab(hrp, addr.slice(0, addr.length - 1) + ch);
  }
}

// ------------------------------------------------ 7. non-ASCII / multi-byte
for (const ch of HIGH) {
  ab('bc', SHORT + ch);
  ab('bc', ch + SHORT);
  ab('bc', SHORT.slice(0, 3) + ch + SHORT.slice(4));
  ab('bc', SHORT.slice(0, 3) + ch + SHORT.slice(3));
  ab('bc', ch);
  ab(ch, SHORT);
  ab('bc' + ch, SHORT);
  ab(ch, ch);
}
// emoji sequences, ZWJ, flags, skin tones, variation selectors, lone surrogates
for (const s of [
  C(0x1f469) + C(0x200d) + C(0x1f4bb),
  C(0x1f1fa) + C(0x1f1f8),
  C(0x1f44d) + C(0x1f3fd),
  C(0x2764) + C(0xfe0f),
  'e' + C(0x301),
  C(0x229) + C(0x301),
  C(0x1f3f4) + C(0xe0067) + C(0xe0062),
  'a' + C(0x200b) + 'b',
  '\ud800', '\udfff', '\ud83d', '\udc00\ud800',
]) {
  ab('bc', SHORT + s);
  ab('bc', s + SHORT);
  ab('bc', s);
  ab(s, SHORT);
  ab(s, s);
}
// non-ASCII spliced into a valid uppercase address (mixed-case interaction)
for (const ch of [C(0x130), C(0x131), C(0x17f), C(0xdf), C(0x212a), C(0xe9)]) {
  const U = SHORT.toUpperCase();
  ab('bc', U + ch);
  ab('bc', ch + U);
  ab('bc', U.slice(0, 5) + ch + U.slice(6));
}

// ------------------------------------------------ 8. whitespace / trimming bait
for (const w of [' ', '  ', '\t', '\n', '\r\n', C(0xa0), C(0x3000), C(0x200b), '\v', '\f']) {
  ab('bc', w + SHORT);
  ab('bc', SHORT + w);
  ab('bc', w + SHORT + w);
  ab('bc' + w, SHORT);
  ab(w + 'bc', SHORT);
  ab('bc', w);
}

// ------------------------------------------------ 9. argparse x weird bytes
for (const v of ['-', '- ', ' -x', '-\t', '-\n', '-1', '-0', '-1.5', '-.5',
  '-x', '-5x', '--', C(0xe9), C(0x1f600), '', ' ', '\t', DEL, C(1)]) {
  add(['--a', v, '--b', SHORT]);
  add(['--a', 'bc', '--b', v]);
}
add(['--a' + C(0xe9), 'bc', '--b', SHORT]);
add(['--a', 'bc', '--b', SHORT, C(0xe9)]);
add(['--a', 'bc', '--b', SHORT, '']);
add(['--a', 'bc', '--b', SHORT, '\n']);
add(['--a', 'bc', '--b', SHORT, '\t', '']);
add(['--' + C(0x1f600), 'bc']);
add(['-h' + C(0x1f600)]);
add(['-h' + C(0xe9), '--a', 'bc']);
add(['--a=\t', '--b=\n']);
add(['--a=bc', '--b=' + SHORT.slice(0, 3) + C(0xe9) + SHORT.slice(4)]);
add(['--b=' + SHORT, '--a=bc']);
add([]);
add(['--a', 'bc']);
add(['--b', SHORT]);

// -------------------------------- 10. checksum chars: every CHARSET member swap
for (const ch of CHARSET) {
  ab('bc', SHORT.slice(0, 3) + ch + SHORT.slice(4));
  ab('bc', SHORT.slice(0, 13) + ch);
}

// -------------------------------- 11. raw bech32 strings, tiny data parts
for (const d of [[], [0], [0, 0], [1], [31], [0, 31]]) {
  const raw = bech32Encode('bc', d);
  ab('bc', raw);
  ab('bc', raw + '1');
  ab('bc', raw + 'b');
  ab('bc', raw.slice(0, -1) + 'i');
  ab('bc', raw.slice(0, -1) + 'o');
}

// -------------------------------- 12. separator-only / truncated strings
for (const s of ['bc1', 'bc11', 'bc1q', 'bc1qqqqq', 'bc1qqqqqq', 'bc1qqqqqqq',
  'bc1gmk9yu', 'bc1gmk9y', 'bc1gmk9yu1', '1bc1gmk9yu']) {
  ab('bc', s);
}

writeFileSync('/tmp/corpus/charset-and-bytes.json', JSON.stringify(cases));
console.log('cases=' + cases.length);

