  'bc1gmk9yu', 'bc1gmk9y', 'bc1gmk9yu1', '1bc1gmk9yu']) {
  ab('bc', s);
}

// -------- 13. EXHAUSTIVE: every printable ASCII at every index of a 14-char addr
for (let i = 0; i < SHORT.length; i += 1) {
  for (let cp = 33; cp <= 126; cp += 1) {
    ab('bc', SHORT.slice(0, i) + C(cp) + SHORT.slice(i + 1));
  }
}

// -------- 14. EXHAUSTIVE: every sub-33 byte + DEL at every index (sub + insert)
const LOWBYTES = [];
for (let cp = 1; cp <= 32; cp += 1) LOWBYTES.push(cp);
LOWBYTES.push(127);
for (let i = 0; i < SHORT.length; i += 1) {
  for (const cp of LOWBYTES) ab('bc', SHORT.slice(0, i) + C(cp) + SHORT.slice(i + 1));
}
for (let i = 0; i <= SHORT.length; i += 1) {
  for (const cp of LOWBYTES) ab('bc', SHORT.slice(0, i) + C(cp) + SHORT.slice(i));
}

// -------- 15. every position of the 42-char p2wpkh x the four excluded chars
for (const ch of ['1', 'b', 'i', 'o']) {
  for (let i = 0; i < P2WPKH.length; i += 1) {
    ab('bc', P2WPKH.slice(0, i) + ch + P2WPKH.slice(i + 1));
  }
}

// -------- 16. mixed-case bait: one ASCII char spliced into an UPPERCASE address
const UP = P2WPKH.toUpperCase();
for (let cp = 33; cp <= 126; cp += 1) {
  const ch = C(cp);
  ab('bc', UP.slice(0, 5) + ch + UP.slice(6));
  ab('bc', UP + ch);
  ab('bc', ch + UP);
}

// -------- 17. Python repr() of a str: reached via `ignored explicit argument`
// argparse renders the explicit argument with repr(), so every non-printable
// code point and the quote-selection rule are observable on stderr.
const REPR_CPS = [];
for (let cp = 1; cp <= 127; cp += 1) REPR_CPS.push(cp);          // C0 + ASCII + DEL
for (let cp = 0x80; cp <= 0xa1; cp += 1) REPR_CPS.push(cp);      // C1 + NBSP + inverted !
for (const cp of [
  0xad, 0xff, 0x100, 0x130, 0x131, 0x17f, 0x300, 0x301, 0x34f, 0x378, 0x600,
  0x61c, 0x70f, 0x1680, 0x180e, 0x2000, 0x2007, 0x200b, 0x200c, 0x200d, 0x200e,
  0x2028, 0x2029, 0x202f, 0x2060, 0x2065, 0x20bf, 0x212a, 0x2fffe, 0x3000, 0xd7ff,
  0xe000, 0xf8ff, 0xfdd0, 0xfeff, 0xfff9, 0xfffd, 0xfffe, 0xffff,
  0x10000, 0x1000c, 0x1049e, 0x1d173, 0x1f600, 0xe0001, 0xe0020, 0xe0067,
  0xf0000, 0xffffd, 0x10fffd, 0x10ffff,
]) REPR_CPS.push(cp);
for (const cp of REPR_CPS) {
  add(['--help=' + C(cp)]);
}
for (const s of [
  '', 'x', "'", '"', "a'b", 'a"b', "a'\"b", '\\', "\\'", '\\\\', "''", '""',
  '\n', '\r', '\t', '\v', '\f', '\x07', '\x1b', '\x00'.slice(1) + '\x1f',
  "it's", 'say "hi"', "both ' and \"", '́́', 'é',
  C(0x1f600) + C(0x200d) + C(0x1f600), '\ud800', '\udfff',
  'tab\there', 'nl\nhere', C(0xa0) + "'" , "'" + C(0xa0),
]) {
  add(['--help=' + s]);
  add(['--h=' + s]);
  add(['--a', 'bc', '--b', SHORT, '--help=' + s]);
}
// the same repr path via other spellings of the help option
for (const s of ['\n', '\t', C(1), C(0x80), C(0xa0), C(0x200b), "a'b"]) {
  add(['--he=' + s]);
  add(['--hel=' + s]);
  add(['--help=' + s, '--a', 'bc']);
  add(['--a=bc', '--help=' + s]);
}
// raw (non-repr) echo path: `unrecognized arguments` must stay byte-identical
for (const cp of [1, 9, 10, 13, 27, 31, 127, 0x80, 0xa0, 0xe9, 0x200b, 0xfeff, 0x1f600]) {
  add(['--a', 'bc', '--b', SHORT, C(cp)]);
  add(['--a', 'bc', '--b', SHORT, 'x' + C(cp) + 'y']);
}

